// Decode parses a TOML document and returns its root table. Tables are
// map[string]any; strings are string, integers int64, floats float64 and
// booleans bool.
// A document that is not valid TOML, or that uses a part of TOML this
// package does not implement, is refused with a *ParseError and no table.
//
//charter:realizes SW-261126-BPDX
	chartertest.Verifies(t, claims.STK_261126_Y8PN, "config-decodes")
	doc := `# The service's configuration
title = "TOML \"example\""
"quoted key" = 'C:\temp'
owner.name = "Tom"

[server]
port = 8080  # the default
debug = false

[server.limits]
max-conns = -1
`
	want := map[string]any{
